-- Cambridge 271-275 postflight.
PRAGMA foreign_keys=ON;CREATE TABLE _fg(valid INTEGER CHECK(valid=1));CREATE TABLE _sr (id TEXT,subject_id TEXT,topic_id TEXT,question_text TEXT,question_type TEXT,options TEXT,correct_answer TEXT,explanation TEXT,difficulty TEXT,points INTEGER,marks INTEGER,time_limit INTEGER);INSERT INTO _sr (id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) SELECT id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit FROM questions WHERE (id GLOB 'q_alevel_bio_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_chem_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_fm_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_math_[0-9][0-9][0-9]' OR id GLOB 'q_alevel_phy_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_addmath_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_bio_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_chem_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_math_[0-9][0-9][0-9]' OR id GLOB 'q_igcse_phy_[0-9][0-9][0-9]');CREATE TABLE _sf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _sf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,topic_id,question_text,question_type,options,correct_answer,explanation,difficulty,points,marks,time_limit) FROM (SELECT q.* FROM questions q JOIN _sr s ON s.id=q.id)),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;CREATE TABLE _tf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _tf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY id),json_array(id,subject_id,parent_id,name,slug,description,theory_content,key_formulas,display_order,created_at) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration')),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;CREATE TABLE _lf(c INTEGER,n INTEGER,a INTEGER,b INTEGER);INSERT INTO _lf(c,n,a,b) WITH RECURSIVE r(k,v) AS (SELECT row_number() OVER(ORDER BY migration_id,entity_type,entity_id,field_name,old_value,new_value),json_array(migration_id,entity_type,entity_id,field_name,old_value,new_value) FROM question_bank_remediation_log WHERE migration_id IN('271_cambridge_topic_remediation_part_1','272_cambridge_topic_remediation_part_2','273_cambridge_topic_remediation_part_3','274_cambridge_topic_remediation_part_4','275_cambridge_topic_remediation_part_5')),w(k,i,n,a,b,v) AS (SELECT k,0,length(v),7,11,v FROM r UNION ALL SELECT k,i+1,n,(a*131+unicode(substr(v,i+1,1)))%2147483647,(b*137+unicode(substr(v,i+1,1)))%2147483629,v FROM w WHERE i<n),f AS (SELECT k,n,a,b FROM w WHERE i=n) SELECT count(*) c,coalesce(sum(n),0) n,coalesce(sum((a*k)%2147483647)%2147483647,0) a,coalesce(sum((b*k)%2147483629)%2147483629,0) b FROM f;INSERT INTO _fg SELECT CASE WHEN (SELECT c=455 AND n=137254 AND a=1772630358 AND b=1804962429 FROM _sf) AND (SELECT c=453 AND n=53415 AND a=2055164836 AND b=781945770 FROM _lf) AND (SELECT COUNT(*) FROM topics WHERE id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration'))=15 AND (SELECT c=15 AND n=3101 AND a=958063944 AND b=1971966840 FROM _tf) AND NOT EXISTS(SELECT 1 FROM topics n JOIN topics o ON o.subject_id=n.subject_id AND o.id<>n.id AND (o.name=n.name OR o.slug=n.slug) WHERE n.id IN('topic_igcse_chem_electrolysis','topic_igcse_chem_analysis','topic_igcse_bio_cell_transport','topic_igcse_bio_excretion','topic_igcse_bio_coordination','topic_igcse_addmath_series','topic_alevel_phys_medical','topic_alevel_phys_particles','topic_alevel_bio_immunity','topic_alevel_math_diffeq','topic_alevel_fmath_summation','topic_alevel_fmath_induction','topic_alevel_fmath_polynomial_roots','topic_alevel_fmath_vectors','topic_alevel_fmath_integration')) AND (SELECT COUNT(*) FROM _sr)=455 AND (SELECT COUNT(*) FROM _sr WHERE subject_id LIKE 'subj_igcse_%' AND topic_id IS NOT NULL)=225 AND (SELECT COUNT(*) FROM _sr WHERE subject_id LIKE 'subj_alevel_%' AND topic_id IS NOT NULL)=225 AND (SELECT COUNT(*) FROM _sr WHERE id IN('q_alevel_bio_028','q_alevel_bio_029','q_alevel_fm_051','q_alevel_fm_052','q_alevel_fm_053') AND topic_id IS NULL)=5 AND NOT EXISTS(SELECT 1 FROM pragma_foreign_key_check) AND NOT EXISTS(SELECT 1 FROM _sr q JOIN topics t ON t.id=q.topic_id WHERE q.topic_id IS NOT NULL AND q.subject_id<>t.subject_id) THEN 1 ELSE 0 END;DROP TABLE _lf;DROP TABLE _tf;DROP TABLE _sf;DROP TABLE _sr;DROP TABLE _fg;
